import mq3.client.ui_gameinfo_missionpack as game
import mq3.shared.info as info
function valueOrNull(value,key) if value==void then return "null" end if;return info.value(value,key) end function
function main(args)
  state=game.create(false);parsed=game.UI_ParseInfos(state,"// comment\n{ name Sarge model sarge/default } { name Visor model visor/default }",4);print("parse|"+str(len(parsed))+"|"+info.value(parsed[0],"name")+"|"+info.value(parsed[1],"model"));limited=game.UI_ParseInfos(state,"{ a 1 } { b 2 }",1);print("limit|"+str(len(limited)));state.data.bots=parsed;game.sync(state);print("number|"+valueOrNull(game.UI_GetBotInfoByNumber(state,1),"name")+"|"+valueOrNull(game.UI_GetBotInfoByNumber(state,-1),"name"));print("name|"+valueOrNull(game.UI_GetBotInfoByName(state,"sArGe"),"model")+"|"+valueOrNull(game.UI_GetBotInfoByName(state,"none"),"model"));print("count|"+str(game.UI_GetNumBots(state))+"|"+game.UI_GetBotNameByNumber(state,0)+"|"+game.UI_GetBotNameByNumber(state,99));arenaFile="{ map a longname Alpha type \"ffa tourney\" } { map b longname Beta type \"ctf oneflag overload harvester\" } { map c longname Gamma } { map d longname Delta type FFA }";game.UI_LoadArenas(state,"scripts/arenas.txt",arenaFile,[]);print("arenas|"+str(len(state.maps))+"|"+state.maps[0].mapLoadName+"|"+str(state.maps[0].typeBits)+"|"+str(state.maps[1].typeBits)+"|"+str(state.maps[2].typeBits)+"|"+str(state.maps[3].typeBits)+"|"+state.maps[0].imageName);game.UI_LoadBots(state,"scripts/bots.txt","{ name Sarge model sarge/default } { name Visor model visor/default }",[]);print("bots|"+str(game.UI_GetNumBots(state))+"|"+game.UI_GetBotNameByNumber(state,0)+"|"+game.UI_GetBotNameByNumber(state,1));return 0
end function
